<script setup>
import { ref } from 'vue'; import { router, useForm } from '@inertiajs/vue3';
defineProps({ plans: Array }); const editing=ref(null); const empty={name:'',installment_count:2,schedule_mode:'evenly_spaced',adjustment_direction:'fee',adjustment_mode:'fixed',adjustment_value:0}; const form=useForm({...empty});
function edit(p){editing.value=p;form.defaults({name:p.name,installment_count:p.installment_count,schedule_mode:p.schedule_mode,adjustment_direction:p.adjustment_direction,adjustment_mode:p.adjustment_mode,adjustment_value:p.adjustment_value});form.reset();form.clearErrors()} function cancel(){editing.value=null;form.defaults({...empty});form.reset()} function submit(){const o={preserveScroll:true,onSuccess:cancel};editing.value?form.put(`/admin/plans-paiement/${editing.value.id}`,o):form.post('/admin/plans-paiement',o)} const remove=p=>confirm(`Supprimer « ${p.name} » ?`)&&router.delete(`/admin/plans-paiement/${p.id}`,{preserveScroll:true});
</script>
<template><section class="grid gap-6 lg:grid-cols-[.65fr_1.35fr]"><div class="rounded-3xl bg-white p-6"><p class="text-xs font-bold uppercase text-coral">{{editing?'Modification':'Nouveau'}}</p><h2 class="mt-2 font-serif text-3xl">Plan de paiement</h2><form @submit.prevent="submit" class="mt-6 space-y-4"><input v-model="form.name" class="w-full rounded-xl border px-4 py-3" placeholder="Paiement en 3 fois"/><input v-model="form.installment_count" type="number" min="2" max="24" class="w-full rounded-xl border px-4 py-3"/><select v-model="form.schedule_mode" class="w-full rounded-xl border bg-white px-4 py-3"><option value="evenly_spaced">Répartition équivalente</option><option value="monthly_end">Chaque fin de mois</option></select><div class="grid grid-cols-2 gap-2"><select v-model="form.adjustment_direction" class="rounded-xl border bg-white px-3 py-3"><option value="fee">Frais</option><option value="discount">Remise</option></select><select v-model="form.adjustment_mode" class="rounded-xl border bg-white px-3 py-3"><option value="fixed">CHF</option><option value="percentage">%</option></select></div><input v-model="form.adjustment_value" type="number" min="0" step=".01" class="w-full rounded-xl border px-4 py-3"/><p v-if="Object.keys(form.errors).length" class="text-xs text-red-600">{{Object.values(form.errors)[0]}}</p><div class="flex gap-2"><button v-if="editing" type="button" @click="cancel" class="flex-1 rounded-full border py-3">Annuler</button><button class="flex-1 rounded-full bg-ink py-3 font-bold text-white">Enregistrer</button></div></form></div><div class="overflow-hidden rounded-3xl bg-white"><div class="border-b p-5"><h2 class="font-serif text-2xl">Plans proposés</h2></div><table v-if="plans.length" class="w-full text-left"><thead class="bg-[#f7f5f0] text-xs text-black/45"><tr><th class="p-4">Plan</th><th class="p-4">Échéances</th><th class="p-4 text-right">Actions</th></tr></thead><tbody><tr v-for="p in plans" :key="p.id" class="border-t"><td class="p-5 font-bold">{{p.name}}</td><td class="p-5">{{p.installment_count}} factures</td><td class="p-5"><div class="flex justify-end gap-2"><button @click="edit(p)" class="grid h-9 w-9 place-items-center rounded-full bg-black/5" title="Modifier">✎</button><button @click="remove(p)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500" title="Supprimer">×</button></div></td></tr></tbody></table><p v-else class="p-16 text-center text-black/40">Aucun plan.</p></div></section></template>
